args.newString:
function update() {
    if (gameOver) return;

    const nextX = player.x + (keys['ArrowLeft'] ? -player.speed : keys['ArrowRight'] ? player.speed : 0);
    const nextY = player.y + (keys['ArrowUp'] ? -player.speed : keys['ArrowDown'] ? player.speed : 0);

    let blocked = false;
    walls.forEach(w => {
        if (nextX < w.x + w.w && nextX + player.size > w.x && nextY < w.y + w.h && nextY + player.size > w.y) blocked = true;
    });
    if (!blocked) { player.x = nextX; player.y = nextY; }

    if (keys['Space']) {
        bullets.push({ x: player.x, y: player.y, vx: 0, vy: -5 });
        keys['Space'] = false; 
    }

    bullets.forEach((b, i) => {
        b.y += b.vy;
        walls.forEach(w => {
            if (b.x < w.x + w.w && b.x + 4 > w.x && b.y < w.y + w.h && b.y + 4 > w.y) b.dead = true;
        });
        if (b.y < 0 || b.dead) bullets.splice(i, 1);
    });

    enemies.forEach((en, i) => {
        const dx = player.x - en.x;
        const dy = player.y - en.y;
        const dist = Math.sqrt(dx*dx + dy*dy);
        const nx = en.x + (dx/dist) * en.speed;
        const ny = en.y + (dy/dist) * en.speed;

        let wallHit = false;
        walls.forEach(w => {
            if (nx < w.x + w.w && nx + en.size > w.x && ny < w.y + w.h && ny + en.size > w.y) wallHit = true;
        });
        if (wallHit) enemies.splice(i, 1);
        else { en.x = nx; en.y = ny; }

        if (dist < player.size) {
            lives--;
            livesEl.innerText = lives;
            enemies = [];
            player.x = 300; player.y = 200;
            if (lives <= 0) gameOver = true;
        }

        bullets.forEach((b, bi) => {
            const bdx = b.x - en.x;
            const bdy = b.y - en.y;
            if (Math.sqrt(bdx*bdx + bdy*bdy) < 10) {
                enemies.splice(i, 1);
                bullets.splice(bi, 1);
                score += 100;
                scoreEl.innerText = score;
            }
        });
    });

    if (Math.random() < 0.02) spawnEnemy();
}

