function findSafeSpawn() {
    for (let i = 0; i < 50; i++) {
        const side = Math.floor(Math.random() * 4);
        let x, y;
        if (side === 0) { x = Math.random() * canvas.width; y = 0; }
        else if (side === 1) { x = Math.random() * canvas.width; y = canvas.height; }
        else if (side === 2) { x = 0; y = Math.random() * canvas.height; }
        else { x = canvas.width; y = Math.random() * canvas.height; }

        let hit = false;
        walls.forEach(w => { if (x < w.x + w.w && x + 10 > w.x && y < w.y + w.h && y + 10 > w.y) hit = true; });
        if (!hit) return { x, y };
    }
    console.warn("Safe spawn not found");
    return { x: 50, y: 50 };
}

function spawnEnemy() {
    const pos = findSafeSpawn();
    enemies.push({ x: pos.x, y: pos.y, size: 10, speed: 1.5, color: '#f00', cooldown: 60 });
}

