args.newString:
function drawPlayer(p) {
    ctx.strokeStyle = p.color;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(p.x, p.y-7, 3, 0, Math.PI*2);
    ctx.moveTo(p.x, p.y-4); ctx.lineTo(p.x, p.y+1);
    ctx.moveTo(p.x-4, p.y-2); ctx.lineTo(p.x+4, p.y-2);
    ctx.moveTo(p.x, p.y+1); ctx.lineTo(p.x-3, p.y+5);
    ctx.moveTo(p.x, p.y+1); ctx.lineTo(p.x+3, p.y+5);
    ctx.stroke();
}

function drawEnemy(en) {
    ctx.strokeStyle = en.color;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(en.x, en.y-7, 3, 0, Math.PI*2);
    ctx.moveTo(en.x, en.y-4); ctx.lineTo(en.x, en.y+1);
    ctx.moveTo(en.x-4, en.y-2); ctx.lineTo(en.x+4, en.y-2);
    ctx.moveTo(en.x, en.y+1); ctx.lineTo(en.x-3, en.y+5);
    ctx.moveTo(en.x, en.y+1); ctx.lineTo(en.x+3, en.y+5);
    ctx.stroke();
}

function draw() {
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    drawPlayer(player);

    ctx.fillStyle = '#fff';
    bullets.forEach(b => ctx.fillRect(b.x-2, b.y-2, 4, 4));
    ctx.fillStyle = '#f0f';
    enemyBullets.forEach(eb => ctx.fillRect(eb.x-2, eb.y-2, 4, 4));

    enemies.forEach(drawEnemy);

    ctx.strokeStyle = '#0f0';
    ctx.lineWidth = 2;
    walls.forEach(w => ctx.strokeRect(w.x, w.y, w.w, w.h));

    ctx.fillStyle = '#0f0';
    ctx.font = '20px monospace';
    ctx.fillText(`Score: ${score}`, 20, 30);
    ctx.fillText(`Lives: ${lives}`, 520, 30);

    if (gameOver) {
        ctx.fillStyle = '#f00';
        ctx.font = '40px monospace';
        ctx.fillText('GAME OVER', 220, 200);
    }
}

