function findSafeSpawn() {
    for (let i = 0; i < 50; i++) {
        const side = Math.floor(Math.random() * 4);
        let x, y;
        if (side === 0) { x = Math.random() * (canvas.width - 20) + 10; y = 11; }
        else if (side === 1) { x = Math.random() * (canvas.width - 20) + 10; y = canvas.height - 21; }
        else if (side === 2) { x = 11; y = Math.random() * (canvas.height - 20) + 10; }
        else { x = canvas.width - 21; y = Math.random() * (canvas.height - 20) + 10; }

        let hit = false;
        walls.forEach(w => { if (x < w.x + w.w && x + 10 > w.x && y < w.y + w.h && y + 10 > w.y) hit = true; });
        if (!hit) return { x, y };
    }
    console.warn("Safe spawn not found");
    return { x: 50, y: 50 };
}

